/**
 * @distilled.cloud/exa -- Exa SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from Exa's OpenAPI documents (mirrored
 * at `specs/spec-mirror-exa/specs/`). Everything else in this folder is
 * hand-written.
 *
 * One module per API: `api` (search, contents, answer, monitors, agent runs,
 * batches, Websets) and `teamManagement` (API keys and credits).
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Exa from "@distilled.cloud/exa";
 *
 * const program = Exa.api.search({ query: "Effect TypeScript", numResults: 3 });
 *
 * program.pipe(
 *   Effect.provide(Layer.mergeAll(FetchHttpClient.layer, Exa.CredentialsFromEnv, Exa.ExaProtocol)),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ExaProtocol,
  ExaTeamManagementProtocol,
  type ExaOpError,
  type ExaOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
